package com.littlemakers.village.nativeapp;
public final class AdventureStateTest {
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static void walk(AdventureState s){for(int i=0;i<1500&&s.moving;i++)s.advance(.016f,false);}
 public static void main(String[]args){AdventureState s=new AdventureState();for(int i=0;i<3;i++){s.nextClue();walk(s);check(s.nearSeed()>=0,"guided route blocked at seed "+i+" ("+s.x+","+s.z+")");check(s.interact()==1,"seed collection failed");check(s.seeds()==i+1,"incorrect count");check(s.interact()==0,"duplicate seed collected");}s.nextClue();walk(s);check(s.nearBridge(),"bridge route blocked");check(s.interact()==2&&s.interact()==2&&s.interact()==3,"bridge did not consume three seeds");check(s.interact()==0,"duplicate bridge completion");check(s.rescue==0,"rescue reaction not started");s.advance(.05f,false);check(s.rescue>0,"turtle did not react");s.advance(.05f,true);check(s.rescue==1,"reduced-motion rescue did not settle");String saved=s.save();AdventureState restored=new AdventureState();restored.restore(saved);check(restored.bridge==3&&restored.seeds()==3,"save lost mission");restored.nextClue();walk(restored);check(restored.z<-3.3f,"completed bridge not traversable");AdventureState empty=new AdventureState();empty.target(0,-4.2f);walk(empty);check(empty.z>=-3.2f,"unfinished bridge crossed");empty.target(999,999);walk(empty);check(AdventureState.land(empty.x,empty.z),"island bounds escaped");empty.restore("NaN,0,7,3,0");check(Float.isFinite(empty.x),"invalid save accepted");empty.joystick(Float.NaN,Float.POSITIVE_INFINITY);empty.advance(Float.NaN,false);check(Float.isFinite(empty.seconds),"invalid delta poisoned state");empty.turn(999);check(empty.yaw==70,"camera unbounded");float time=empty.seconds;empty.advance(.05f,true);check(empty.seconds==time,"reduced-motion clock moved");restored.reset();check(restored.bridge==0&&restored.collected==0&&restored.z==4,"parent reset failed");
 AdventureState joy=new AdventureState();joy.joystick(0,-1);joy.advance(.05f,false);check(joy.z<4&&Math.abs(joy.x)<.001,"joystick did not steer");joy.joystick(0,0);float stopped=joy.z;joy.advance(.05f,false);check(joy.z==stopped,"joystick did not stop");HabitatState h=new HabitatState();check(!h.place(5,0),"locked decor placed");check(h.place(0,0),"starter decor unavailable");h.select(8);check(h.place(5,6),"earned decor unavailable");HabitatState h2=new HabitatState();h2.restore(h.save());check(h2.count()==2&&h2.slots[8]==5,"habitat save lost layout");h2.restore("0,0,0,0,0,0,0,0,99");check(h2.count()==2,"invalid layout partially applied");h2.reset();check(h2.count()==0,"habitat reset failed");System.out.println("PASS: guided rescue routes, collision/bounds, finite input, seed accounting, bridge traversal, saves, decor unlocks and parent reset");}
}
